+    registerPatchCommand(program);
+
+    await expect(
+      program.parseAsync(
+        ['patch', 'decisions/test', '--append', 'one', '--replace', 'one', '--with', 'two'],
+        { from: 'user' }
+      )
+    ).rejects.toThrow(
+      'Select exactly one patch mode: --append, --replace with --with, or --section with --content.'
+    );
+  });
+});

