+    expect(clawCmd).toHaveBeenNthCalledWith(2, "nodes pending --json", {
+      quiet: true,
+      timeoutMs: 5000,
+    });
+  });
+
+  it("falls back to status-derived pending nodes when pending command fails", async () => {
+    const clawCmd = vi.fn(async (cmd) => {
+      if (cmd === "nodes status --json") {
+        return {
+          ok: true,
